using System.Text.Json;
using FugaTES.Integracao.Guardian.Transportadoras;
namespace FugaTES.CarrierBinding.R37.Tests;
public sealed class GuardianCarrierCreateBodyR37Tests
{
 static JsonElement Sap(string name="\"Synthetic Name\"",string legal="\"Synthetic Legal\"",string bp="001234")=>JsonDocument.Parse($"{{\"BusinessPartner\":\"{bp}\",\"BusinessPartnerName\":{name},\"BusinessPartnerFullName\":{legal}}}").RootElement.Clone();
 static GuardianCarrierCreateFieldsR37 Fields(string? code="GUARDIAN_EXPLICIT",string? fiscal="SYNTHETIC_FISCAL",int? estado=1,int? sequential=0,string? callback="https://callback.example.invalid/carrier",bool approved=true)=>new(){BusinessPartner="001234",GuardianCode=code,FiscalIdentifier=fiscal,Estado=estado,Sequencial=sequential,Callback=callback,EvidenceReference="synthetic-contract-only",CodeApproved=approved,SapIdentityConfirmed=approved,FiscalBindingApproved=approved,EstadoBindingApproved=approved,SequencialBindingApproved=approved,CallbackBindingApproved=approved,RequiredFieldContractApproved=approved};
 [Fact] public void NestedSerializationPreservesExplicitFieldsWithoutBpFallback(){var r=GuardianCarrierCreateBodyR37.Prepare(Sap(),Fields());Assert.True(r.Ready);using var d=JsonDocument.Parse(r.TransientBody!);var root=d.RootElement;Assert.Equal(2,root.EnumerateObject().Count());Assert.Equal("https://callback.example.invalid/carrier",root.GetProperty("voConfiguracao").GetProperty("urlParaRetorno").GetString());var t=root.GetProperty("entidadeTransportadora");Assert.Equal(6,t.EnumerateObject().Count());Assert.Equal("GUARDIAN_EXPLICIT",t.GetProperty("codigo").GetString());Assert.Equal("Synthetic Name",t.GetProperty("descricao").GetString());Assert.Equal("Synthetic Legal",t.GetProperty("razaoSocial").GetString());Assert.Equal("SYNTHETIC_FISCAL",t.GetProperty("cnpj").GetString());Assert.Equal(1,t.GetProperty("estado").GetInt32());Assert.Equal(0,t.GetProperty("sequencial").GetInt32());Assert.False(t.TryGetProperty("tipoDocumento",out _));}
 [Theory][InlineData(null,"tax",1,0,"https://callback.example.invalid/")][InlineData("code",null,1,0,"https://callback.example.invalid/")][InlineData("code","tax",null,0,"https://callback.example.invalid/")][InlineData("code","tax",1,null,"https://callback.example.invalid/")][InlineData("code","tax",1,0,null)] public void MissingFieldBlocks(string? code,string? fiscal,int? estado,int? sequential,string? callback){var r=GuardianCarrierCreateBodyR37.Prepare(Sap(),Fields(code,fiscal,estado,sequential,callback));Assert.False(r.Ready);Assert.Null(r.TransientBody);}
 [Theory][InlineData("null")][InlineData("123")][InlineData("true")][InlineData("{}")][InlineData("\"\"")][InlineData("\"   \"")] public void WrongOrEmptySapTypeBlocks(string value){var r=GuardianCarrierCreateBodyR37.Prepare(Sap(value),Fields());Assert.False(r.Ready);Assert.Null(r.TransientBody);}
 [Fact] public void MissingLegalNameBlocks(){Assert.False(GuardianCarrierCreateBodyR37.Prepare(Sap(legal:"null"),Fields()).Ready);}
 [Fact] public void IdentityMismatchBlocks(){Assert.False(GuardianCarrierCreateBodyR37.Prepare(Sap(bp:"1234"),Fields()).Ready);}
 [Fact] public void LongNameBlocksWithoutTruncation(){Assert.False(GuardianCarrierCreateBodyR37.Prepare(Sap(JsonSerializer.Serialize(new string('x',51))),Fields()).Ready);}
 [Fact] public void NoImplicitApprovals(){var r=GuardianCarrierCreateBodyR37.Prepare(Sap(),Fields(approved:false));Assert.False(r.Ready);Assert.Null(r.TransientBody);}
 [Theory][InlineData("http://callback.example.invalid/")][InlineData("https://user:password@callback.example.invalid/")][InlineData("relative-path")] public void UnsafeCallbackBlocks(string callback){Assert.False(GuardianCarrierCreateBodyR37.Prepare(Sap(),Fields(callback:callback)).Ready);}
 [Fact] public void MissingOneApprovalBlocks(){var r=GuardianCarrierCreateBodyR37.Prepare(Sap(),new(){BusinessPartner="001234",GuardianCode="EXPLICIT",FiscalIdentifier="SYNTHETIC",Estado=1,Sequencial=0,Callback="https://callback.example.invalid/",EvidenceReference="synthetic",SapIdentityConfirmed=true,CodeApproved=true,FiscalBindingApproved=true,EstadoBindingApproved=true,SequencialBindingApproved=true,CallbackBindingApproved=true});Assert.False(r.Ready);Assert.Null(r.TransientBody);}
 [Fact] public void DuplicateSapPropertyBlocks(){using var d=JsonDocument.Parse("{\"BusinessPartner\":\"001234\",\"BusinessPartnerName\":\"A\",\"BusinessPartnerName\":\"B\",\"BusinessPartnerFullName\":\"Legal\"}");Assert.False(GuardianCarrierCreateBodyR37.Prepare(d.RootElement,Fields()).Ready);}
 [Fact] public void ResultDiagnosticDoesNotRevealPersonalFields(){var r=GuardianCarrierCreateBodyR37.Prepare(Sap(),Fields());Assert.DoesNotContain("Synthetic",r.ToString());Assert.DoesNotContain("SYNTHETIC_FISCAL",Fields().ToString());}
 [Fact] public void MissingSapObjectBlocks(){Assert.False(GuardianCarrierCreateBodyR37.Prepare(default,Fields()).Ready);}
 [Theory][InlineData("SapIdentityConfirmed")][InlineData("CodeApproved")][InlineData("FiscalBindingApproved")][InlineData("EstadoBindingApproved")][InlineData("SequencialBindingApproved")][InlineData("CallbackBindingApproved")][InlineData("RequiredFieldContractApproved")]
 public void EachUnprovenBindingIndividuallyBlocks(string property){var f=Fields();f.GetType().GetProperty(property)!.SetValue(f,false);var r=GuardianCarrierCreateBodyR37.Prepare(Sap(),f);Assert.False(r.Ready);Assert.Null(r.TransientBody);}
 [Fact] public void ExactSapTextIsNeverNormalized(){var r=GuardianCarrierCreateBodyR37.Prepare(Sap(JsonSerializer.Serialize("  Synthetic Á  ")),Fields());using var d=JsonDocument.Parse(r.TransientBody!);Assert.Equal("  Synthetic Á  ",d.RootElement.GetProperty("entidadeTransportadora").GetProperty("descricao").GetString());}
 [Fact] public void MissingEvidenceReferenceBlocks(){var f=Fields();f.GetType().GetProperty("EvidenceReference")!.SetValue(f,null);Assert.False(GuardianCarrierCreateBodyR37.Prepare(Sap(),f).Ready);}
}
